<?php
declare(strict_types=1);
$app=is_file(__DIR__.'/../app/src/Database.php')?__DIR__.'/../app':'/var/www/html'; foreach(['Database','UserRepository','MailSettingsRepository','MailService','RepresentationOfferRepository','RepresentationContactService'] as $class)require_once "$app/src/$class.php";
$check=static function(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}; $pdo=(new Database(':memory:'))->connection();$now=gmdate('Y-m-d\TH:i:s\Z');
