$duplicate=false;try{$service->send((int)$a['id'],$dated,$future,$text);}catch(DomainException){$duplicate=true;}$check($duplicate&&count($mails)===1,'Doppelversandschutz vor Mailversand.');
$wrong=(new DateTimeImmutable($future))->modify('+1 day')->format('Y-m-d');$rejected=false;try{$service->send((int)$a['id'],$always,$wrong,$text);}catch(InvalidArgumentException){$rejected=true;}$check($rejected,'Immer-Angebot nur am Meeting-Wochentag.');
$discovery=$offers->findForHomeChapter(101,(int)$a['id'],(new DateTimeImmutable('today',new DateTimeZone('Europe/Berlin')))->format('Y-m-d'));$check(count($discovery['datedOffers'])===1&&count($discovery['datedOffers'][0]['providers'])===1&&count($discovery['allDatesOffers'])===1,'Immer-Anbieter ergänzt Termin ohne Personendublette.');
